import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"快速上手","description":"","frontmatter":{},"headers":[],"relativePath":"zh-HK/user-guide/getting-started.md","filePath":"zh-HK/user-guide/getting-started.md","lastUpdated":1787551561000}'),d={name:"zh-HK/user-guide/getting-started.md"};function n(s,e,c,i,l,h){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="快速上手" tabindex="-1">快速上手 <a class="header-anchor" href="#快速上手" aria-label="Permalink to &quot;快速上手&quot;">​</a></h1><h2 id="安裝" tabindex="-1">安裝 <a class="header-anchor" href="#安裝" aria-label="Permalink to &quot;安裝&quot;">​</a></h2><p>在首頁的<a href="./../">下載按鈕</a>獲取最新版本——每次發佈都會提供兩種形式：</p><ul><li><strong>安裝程式</strong>（<code>Lertaro-Setup.exe</code>）—— 推薦使用。會註冊後臺索引服務，也可以設定為隨 Windows 啓動。</li><li><strong>便攜版</strong>（<code>Lertaro-Portable.zip</code>）—— 解壓即可運行，無需安裝。之後仍然可以在 <strong>設定 → 運行狀態</strong> 裏手動安裝後臺服務。如果電腦上還沒有 Lertaro 需要的 .NET 桌面運行時，運行一次自帶的 <code>install-dotnet-runtime.bat</code> 即可——安裝程式會自動處理這一步，但便攜版做不到。便攜版用完不再需要時，沒有解除安裝程式幫你清理：刪除資料夾前，運行自帶的 <code>portable-cleanup.bat</code>。它會在服務已安裝時停止並卸載 Lertaro 後臺服務，同時移除當前使用者的 <code>lertaro://</code> URI 協議註冊和“開機自動啓動”註冊項。卸載服務時可能會請求系統管理員權限，其餘清理針對當前使用者執行。</li></ul><p>這兩種形式都分別提供 <strong>x64</strong> 和 <strong>ARM64</strong> 版本。上面這些是 x64 版本，在絕大多數電腦上都能運行——包括 Windows on ARM 裝置，只是以模擬方式運行。如果用的是 ARM 裝置，建議改用 <code>Lertaro-Setup-arm64.exe</code> 或 <code>Lertaro-Portable-arm64.zip</code>，它們是原生版本。自動更新會一直保持在你安裝時的架構上，所以要換成另一種，需要自己去下載。</p><h2 id="便攜版資料" tabindex="-1">便攜版資料 <a class="header-anchor" href="#便攜版資料" aria-label="Permalink to &quot;便攜版資料&quot;">​</a></h2><p>便攜版會在程式旁將機器資料保存到 <code>Data\\Machine</code>，並把每位使用者的私有資料保存到 <code>Data\\Users\\&lt;SID hash&gt;</code>。如果其 <code>Data</code> 目錄尚未建立，為了兼容會重用已有的 <code>%ProgramData%\\Lertaro</code> 和 <code>%LocalAppData%\\Lertaro</code> 資料；建立 <code>Data</code> 後，該便攜版將優先使用自己的資料並成為自包含副本。</p><p>首次運行時，Lertaro 會安裝並啓動一個 Windows 服務（<code>Lertaro.Service</code>），專門負責檔案索引。這個拆分是有意為之的——如果好奇原因可以參考<a href="./../dev-guide/architecture.html">架構設計</a>——但作為普通使用者，只需要知道：<strong>設定 → 運行狀態</strong> 頁面會告訴你服務是否已安裝、是否在運行，如果還沒安裝，也可以在這裏安裝。</p><h2 id="三種視窗" tabindex="-1">三種視窗 <a class="header-anchor" href="#三種視窗" aria-label="Permalink to &quot;三種視窗&quot;">​</a></h2><p>Lertaro 不是只有一個搜尋視窗——它會根據使用場景自動適配：</p><ul><li><strong>主視窗</strong> —— 從工作列/開始功能表捷徑打開的完整視窗，結果列表最大，還帶有窗內動作面板。</li><li><strong>快速視窗</strong> —— 按下全局呼出熱鍵（預設雙擊 <code>Ctrl</code>）召喚出來的緊湊型置頂彈窗，專為“按熱鍵 → 輸入 → 回車”這套肌肉記憶設計。</li><li><strong>內嵌視窗</strong> —— 直接把 Lertaro 的搜尋框嵌入到受支援的原生檔案對話方塊或檔案總管視窗裏，不用離開當前對話方塊就能搜尋。</li></ul><p>三種視窗共用同一套搜尋引擎、熱鍵系統和動作選單——區別只在於它們出現的位置和形態。</p><h2 id="基本搜尋" tabindex="-1">基本搜尋 <a class="header-anchor" href="#基本搜尋" aria-label="Permalink to &quot;基本搜尋&quot;">​</a></h2><p>最近檔案、收藏夾和歷史記錄不用輸入任何東西就能拿到——它們是<a href="./settings/quick-panel.html">快速面板</a>裏的標籤，而這個面板是疊在當前前景視窗上打開的，並不在搜尋視窗裏面。</p><p>直接開始打字即可。結果會隨輸入實時更新，並按相關度排序（匹配與排序的原理見<a href="./search-syntax.html">搜尋語法</a>）。用<a href="./hotkeys.html">可配置的上/下一項熱鍵</a>（預設是方向鍵）移動選中項，回車打開高亮的結果。</p><p>接下來可以看看 <a href="./search-syntax.html">搜尋語法</a>，充分發揮搜尋框的能力。</p>',16)])])}const u=a(d,[["render",n]]);export{g as __pageData,u as default};
